def decrypt(code, k):
    n = len(code)
    result = [0] * n
    if k == 0:
        return result
    for i in range(n):
        total = 0
        if k > 0:
            for j in range(1, k + 1):
                total += code[(i + j) % n]                                # look ahead, wrapping around the circle
        else:
            for j in range(1, -k + 1):
                total += code[(i - j) % n]                                # look behind, wrapping around the circle
        result[i] = total
    return result


if __name__ == "__main__":
    print(decrypt([5, 7, 1, 4], 3))

