import java.util.*;

public class Main {
    int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) return result;
        for (int i = 0; i < n; i++) {
            int total = 0;
            if (k > 0) {
                for (int j = 1; j <= k; j++) {
                    total += code[(i + j) % n];                                  // look ahead, wrapping around the circle
                }
            } else {
                for (int j = 1; j <= -k; j++) {
                    total += code[((i - j) % n + n) % n];                        // look behind, wrapping around the circle
                }
            }
            result[i] = total;
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(java.util.Arrays.toString(solution.decrypt(new int[]{5, 7, 1, 4}, 3)));
    }
}

